def pigeonhole_sort(arr: list) -> list:
    if not arr:
        return []

    min_value = min(arr)
    max_value = max(arr)
    size = max_value - min_value + 1

    holes = [[] for _ in range(size)]

    for number in arr:
        holes[number - min_value].append(number)

    sorted_arr = []
    for hole in holes:
        sorted_arr.extend(hole)

    return sorted_arr

def binary_search(nums, target):
    """
    Determine if the target exists in the sorted array nums using binary search.
    Returns True if found, else False.
    """
    left, right = 0, len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return True
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return False

