def smallestCommonElement(mat):
    """
    Finds the smallest common element in all rows of a matrix.
    If no such element exists, returns -1.

    :param mat: List[List[int]]
    :return: int
    """
    count = {}
    for row in mat:
        for num in set(row):  # Convert each row to a set to avoid duplicate counts within the same row
            if num in count:
                count[num] += 1
            else:
                count[num] = 1

    rows = len(mat)
    for num in sorted(count.keys()):  # Check the numbers in sorted order
        if count[num] == rows:
            return num
    return -1

