def binary_search(arr, target):
    """
    Perform binary search on a sorted list to find the index of the target.
    If the target is found, return its index. Otherwise, return -1.
    """
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = left + (right - left) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return -1

def is_anagram(s, t):
    if len(s) != len(t):
        return False

    # Initialize a dictionary to count characters
    char_count = {}

    # Count each character in the first string
    for char in s:
        char_count[char] = char_count.get(char, 0) + 1

    # Decrease count for each character found in the second string
    for char in t:
        if char not in char_count:
            return False
        char_count[char] -= 1
        if char_count[char] < 0:
            return False

    # Ensure all counts are zero
    return all(value == 0 for value in char_count.values())

