def min_deletions_to_make_anagrams(word1, word2):
    """
    Returns the minimum number of deletions required to make the two strings anagrams.
    """
    count1 = Counter(word1)
    count2 = Counter(word2)

    # Find the characters that need to be deleted
    deletions = 0
    for char in count1:
        if char in count2:
            deletions += abs(count1[char] - count2[char])
        else:
            deletions += count1[char]

    for char in count2:
        if char not in count1:
            deletions += count2[char]

    return deletions

def quick_sort(arr):
    """
    Function that implements the QuickSort algorithm to sort a given list of integers in ascending order.
    """
    if len(arr) <= 1:
        return arr
    else:
        pivot = arr[len(arr) // 2]
        left = [x for x in arr if x < pivot]
        middle = [x for x in arr if x == pivot]
        right = [x for x in arr if x > pivot]
        return quick_sort(left) + middle + quick_sort(right)

def first_unique_char(input_string: str) -> str:
    """
    Finds and returns the first non-repeating character in the input string.
    If all characters are repeating or the string is empty, returns an empty string.
    """
    # Dictionary to keep track of character frequency
    char_count = {}

    # First pass: count the frequency of each character
    for char in input_string:
        char_count[char] = char_count.get(char, 0) + 1

    # Second pass: find the first character with a frequency of 1
    for char in input_string:
        if char_count[char] == 1:
            return char

    return ""

import heapq

def shortest_path_with_constraints(roads, source, destination, blocked):
    # Create an adjacency list for graph representation
    graph = {}
    for u, v, t in roads:
        if (u, v) in blocked or (v, u) in blocked:
            continue
        if u not in graph:
            graph[u] = []
        if v not in graph:
            graph[v] = []
        graph[u].append((v, t))
        graph[v].append((u, t))

    # Use a priority queue to implement Dijkstra's algorithm
    pq = [(0, source)]  # (distance, node)
    distances = {source: 0}

    while pq:
        current_distance, current_node = heapq.heappop(pq)

        if current_node == destination:
            return current_distance

        if current_distance > distances.get(current_node, float('inf')):
            continue

        for neighbor, weight in graph.get(current_node, []):
            distance = current_distance + weight

            if distance < distances.get(neighbor, float('inf')):
                distances[neighbor] = distance
                heapq.heappush(pq, (distance, neighbor))

    return -1

