    entry_finder = {}
    pq = []
    counter = itertools.count()
    REMOVED = -1

    def add_or_update(node, priority):
        if node in entry_finder:
            entry_finder[node][-1] = REMOVED
        entry = [priority, next(counter), node]
        entry_finder[node] = entry
        heapq.heappush(pq, entry)

