    add_or_update(s, 0)
    while pq:
        priority, _, node = heapq.heappop(pq)
        if node == REMOVED:
            continue
        del entry_finder[node]
        visited.add(node)
        if node == t:
            return priority
        for v, w in graph.get(node, []):
            if v in visited:
                continue
            nd = priority + w
            if nd < dist.get(v, float('inf')):
                dist[v] = nd
                add_or_update(v, nd)
    return -1

